const crypto = require('crypto');
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const url = (j.link || j.url || '').trim();
  if (!url) continue;
  const url_normalized = url.toLowerCase().replace(/\/$/, '').split('?')[0];
  const url_hash = crypto.createHash('sha256').update(url_normalized).digest('hex');
  out.push({
    json: {
      title: j.title || '(sin título)',
      url,
      url_normalized,
      url_hash,
      snippet: j.contentSnippet || j.content || '',
      source_name: j.creator || j.dc_creator || j._source_name || 'Unknown',
      published_at: j.pubDate || j.isoDate || new Date().toISOString(),
      tags: j.categories || []
    }
  });
}
return out;

