const data = $input.item.json.output || $input.item.json;
const original = $('Normalize items').item.json;
const score = (data.relevancia_finanzas_latam || 0) + (data.relevancia_latam || 0) + (data.novedad || 0) + (data.credibilidad_fuente || 0) + (data.potencial_educativo || 0) + (data.potencial_viral || 0) + (data.fit_marca || 0) + (data.accionabilidad || 0) + (data.riesgo || 0);
let classification = 'discard';
if (score >= 70) classification = 'strong';
else if (score >= 60) classification = 'consider';
return { ...original, ...data, total_score: Math.round(score * 100) / 100, classification, signal_score: Math.round(score * 100) / 100 };

const items = $input.all().map(i => i.json).filter(j => j.total_score >= 60).sort((a, b) => b.total_score - a.total_score);
if (items.length === 0) return [];
return [{ json: items[0] }];

