const brief = saved.brief_content;
const compliance = saved.compliance_result;
const score = saved.signal_score;
const sub_cat = saved.sub_categoria;

const text = `*💰 Dinero IA — preview (Fase 1)*\n\n*${brief.title}*\nScore: ${score}/100 (${sub_cat})\nCompliance: *${compliance.verdict}*\n\n*¿Qué pasó?*\n${brief.que_paso}\n\n*¿Por qué importa para tus finanzas?*\n${brief.por_que_importa_finanzas}\n\n*Ángulo:*\n${brief.angulo_finanzas_latam}\n\n*Hook:* _${brief.hook_tentativo}_\n*Formato:* ${brief.formato_recomendado} • *CTA:* ${brief.cta_tentativo}\n*Disclaimer?* ${brief.disclaimer_requerido ? 'sí' : 'no'} • *Productos:* ${(brief.productos_mencionados || []).join(', ') || '—'}\n\n*Prompt sugerido:*\n\`${brief.prompt_o_template_sugerido}\`\n\n*Fuente:* ${saved.source_url}`;

const reply_markup = {
  inline_keyboard: [
    [
      { text: '✅ Aprobar', callback_data: `approve:${brief_id}` },
      { text: '✏️ Editar',  callback_data: `edit:${brief_id}` }
    ],
    [
